@import "@fontsource-variable/public-sans";
@import "@fontsource/instrument-serif";
@import "@fontsource/instrument-serif/400-italic.css";

/* Light (faithful): cream paper (247,241,232), sand panels (239,230,219), warm dark-grey type
   and pills (74,71,65), stone-grey quiet type, one electric blue (42,114,222) for the main CTA,
   warm near-black ink (28,27,26) for hovers. */
:root {
  --background: oklch(0.96 0.014 78);
  --foreground: oklch(0.399 0.011 85);
  --card: oklch(0.929 0.018 73);
  --card-foreground: oklch(0.399 0.011 85);
  --popover: oklch(0.96 0.014 78);
  --popover-foreground: oklch(0.399 0.011 85);
  --primary: oklch(0.399 0.011 85);
  --primary-foreground: oklch(0.96 0.014 78);
  --secondary: oklch(0.929 0.018 73);
  --secondary-foreground: oklch(0.399 0.011 85);
  --muted: oklch(0.893 0.021 75);
  --muted-foreground: oklch(0.53 0.014 80);
  --accent: oklch(0.929 0.018 73);
  --accent-foreground: oklch(0.223 0.002 68);
  --destructive: oklch(0.58 0.2 27);
  --destructive-foreground: oklch(0.96 0.014 78);
  --border: oklch(0.399 0.011 85 / 25%);
  --input: oklch(0.399 0.011 85 / 25%);
  --ring: oklch(0.568 0.18 259);
  --highlight: oklch(0.568 0.18 259);
  --highlight-foreground: oklch(1 0 0);
  --glow: oklch(0.84 0.04 70);
  --chart-1: oklch(0.568 0.18 259);
  --chart-2: oklch(0.7 0.09 190);
  --chart-3: oklch(0.72 0.12 50);
  --chart-4: oklch(0.399 0.011 85);
  --chart-5: oklch(0.723 0.008 81);
  --sidebar: oklch(0.929 0.018 73);
  --sidebar-foreground: oklch(0.399 0.011 85);
  --sidebar-primary: oklch(0.399 0.011 85);
  --sidebar-primary-foreground: oklch(0.96 0.014 78);
  --sidebar-accent: oklch(0.893 0.021 75);
  --sidebar-accent-foreground: oklch(0.223 0.002 68);
  --sidebar-border: oklch(0.399 0.011 85 / 25%);
  --sidebar-ring: oklch(0.568 0.18 259);

  --typeface-body: "Public Sans Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Instrument Serif", "Times New Roman", Georgia, serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.5rem;
  --page-width: 90rem;
  --page-gutter: 1.5rem;
  --section-y: 2.5rem;
}

@media (min-width: 64rem) {
  :root {
    --page-gutter: 4rem;
    --section-y: 5rem;
  }
}

/* Dark: the press band and footer of the original, page-wide. Warm near-black ink, a lighter
   ink for cards, the dark-grey (74,71,65) as the quieter filled surface (arrow circles),
   cream type and cream pills, stone grey (168,165,160) for quiet type. */
.dark {
  --background: oklch(0.223 0.002 68);
  --foreground: oklch(0.96 0.014 78);
  --card: oklch(0.29 0.006 78);
  --card-foreground: oklch(0.96 0.014 78);
  --popover: oklch(0.29 0.006 78);
  --popover-foreground: oklch(0.96 0.014 78);
  --primary: oklch(0.96 0.014 78);
  --primary-foreground: oklch(0.223 0.002 68);
  --secondary: oklch(0.399 0.011 85);
  --secondary-foreground: oklch(0.96 0.014 78);
  --muted: oklch(0.331 0.007 68);
  --muted-foreground: oklch(0.723 0.008 81);
  --accent: oklch(0.331 0.007 68);
  --accent-foreground: oklch(0.96 0.014 78);
  --destructive: oklch(0.68 0.19 25);
  --destructive-foreground: oklch(0.96 0.014 78);
  --border: oklch(0.96 0.014 78 / 12%);
  --input: oklch(0.96 0.014 78 / 18%);
  --ring: oklch(0.65 0.16 259);
  --highlight: oklch(0.62 0.17 259);
  --highlight-foreground: oklch(1 0 0);
  --glow: oklch(0.45 0.03 70);
  --chart-1: oklch(0.65 0.16 259);
  --chart-2: oklch(0.72 0.09 190);
  --chart-3: oklch(0.75 0.12 50);
  --chart-4: oklch(0.96 0.014 78);
  --chart-5: oklch(0.723 0.008 81);
  --sidebar: oklch(0.29 0.006 78);
  --sidebar-foreground: oklch(0.96 0.014 78);
  --sidebar-primary: oklch(0.96 0.014 78);
  --sidebar-primary-foreground: oklch(0.223 0.002 68);
  --sidebar-accent: oklch(0.331 0.007 68);
  --sidebar-accent-foreground: oklch(0.96 0.014 78);
  --sidebar-border: oklch(0.96 0.014 78 / 12%);
  --sidebar-ring: oklch(0.65 0.16 259);
}
